import os
from google.cloud import documentai_v1 as documentai
from google.api_core import future, exceptions

def validate_structured_fields(document_bytes, required_fields):
    """
    Validates that the parsed document contains all required structured fields
    and that each field's confidence score meets or exceeds 0.7.

    Args:
        document_bytes (bytes): Binary content of the invoice document (e.g., PDF).
        required_fields (list[str]): List of required field names (e.g., ['InvoiceNumber', 'TotalAmount']).

    Returns:
        dict: Parsed document contents if valid, or a dict with an 'error' key if invalid.
    """
    # Initialize the Google Cloud Document AI client
    processor_id = "projects/your-project-id/locations/us-central1/processors/your-processor-id"  # Example processor ID
    client = documentai.DocumentProcessorServiceClient()
    name = f"projects/your-project-id/locations/us-central1/processors/{processor_id}"

    # Process the document
    with client.process_document(request={"name": name, "inline_document": {"content": document_bytes, "mime_type": "application/pdf"}}) as response:
        document = response.document

    # Extract field values and confidence scores
    parsed_data = {}
    missing_required = []
    low_confidence = []

    for page in document.pages:
        for entity in page.entities:
            value = entity.mention_text
            confidence = entity.confidence
            for type_ in entity.type_:
                field_name = type_.text
                if field_name in required_fields:
                    if field_name not in parsed_data:
                        parsed_data[field_name] = {"value": value, "confidence": confidence}
                    else:
                        # Handle if the field is present on multiple pages/occurrences
                        parsed_data[field_name]["value"] = value
                        parsed_data[field_name]["confidence"] = max(parsed_data[field_name]["confidence"], confidence)

                    # Check confidence and required presence
                    if confidence < 0.7:
                        low_confidence.append(field_name)
                    break

    # Check validation results
    if missing_required:
        return {"error": f"Missing required fields: {', '.join(missing_required)}"}
    if low_confidence:
        return {"error": f"Fields with low confidence ({', '.join(low_confidence)}): {', '.join([f'{f} ({parsed_data[f][\"confidence\"]})' for f in low_confidence])}"}

    # Validation passed
    return {"parsed_data": parsed_data}
